      isBinary(parent, { left: node }) ||
      isAssignmentExpression(parent, { left: node }) ||
      isUpdateExpression(parent, { prefix: false })
    ) {
      node = parent;
      i--;
      parent = printStack[i];
    } else {
      return false;
    }
  }

  return false;
}

